contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner) public payable {
        require(true);
        require(c.owner() == address(0));
        require(msg.sender != address(0));
        bool reverted;
        try c.transferOwnership(newOwner) { reverted = false; } catch { reverted = true; }
        assert(reverted && c.owner() == address(0));
    }
    receive() external payable {}
}

